"""Random sorted, duplicate-free arrays, with targets chosen both from
inside the array (a hit) and strictly between/outside its elements (a
miss, exercising every insertion point including the two ends)."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(1, 20)
    values = sorted(rng.sample(range(-100, 100), n))
    lines = []
    for _ in range(4):
        if rng.random() < 0.5 and values:
            target = rng.choice(values)
        else:
            target = rng.randint(-110, 110)
            while target in values:
                target = rng.randint(-110, 110)
        lines.append("%d %d" % (n, target))
        lines.append(" ".join(map(str, values)) if values else "")
    return {"name": "an array of %d elements, mixed hits and misses #%d"
                    % (n, index),
            "stdin": "\n".join(lines) + "\n"}
